// Package standing holds a body windows's difference reaches and two it never reaches, for the standing bodies
// (#e4rd5dw): the planted probe reports each function here, saying how many planted literals it heard before it in the
// file, and each planted literal.
package standing

// PlantedReached calls platformName, which each build declares in a file of its own, so windows's difference reaches
// its body.
func PlantedReached() string {
	return platformName() + " planted reached"
}

// PlantedKept says the same in every build, so its body stands in windows's.
func PlantedKept() string {
	return "planted kept"
}

// PlantedKeptAfter says the same in every build too, so its body stands in windows's, after PlantedKept's literal,
// which a build that leaves PlantedKept standing never hears.
func PlantedKeptAfter() int {
	return 2
}
